// Generated by Automated Quality Gate; review before merging.
const { 
  add, 
  subtract, 
  multiply, 
  divide, 
  calculatePercentage, 
  modulo, 
  absoluteDifference 
} = require('../../src/math');

describe('math utility functions', () => {
  
  describe('add', () => {
    test('should add two positive numbers correctly', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should throw TypeError for non-number inputs', () => {
      expect(() => add(1, '2')).toThrow(TypeError);
    });
  });

  describe('subtract', () => {
    test('should subtract numbers correctly', () => {
      expect(subtract(10, 5)).toBe(5);
    });

    test('should return 0 instead of -0', () => {
      expect(Object.is(subtract(0, 0), 0)).toBe(true);
    });
  });

  describe('multiply', () => {
    test('should multiply correctly', () => {
      expect(multiply(2, 4)).toBe(8);
    });

    test('should throw error for infinite numbers', () => {
      expect(() => multiply(Infinity, 1)).toThrow("Inputs must be finite numbers");
    });
  });

  describe('divide', () => {
    test('should divide correctly', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw error when dividing by zero', () => {
      expect(() => divide(10, 0)).toThrow("Cannot divide by zero");
    });
  });

  describe('calculatePercentage', () => {
    test('should calculate percentage correctly', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 if total is 0', () => {
      expect(calculatePercentage(10, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should return correct modulo for positive numbers', () => {
      expect(modulo(10, 3)).toBe(1);
    });

    test('should throw error for modulo by zero', () => {
      expect(() => modulo(5, 0)).toThrow("Cannot modulo by zero");
    });
  });

  describe('absoluteDifference', () => {
    test('should return absolute difference', () => {
      expect(absoluteDifference(10, 20)).toBe(10);
      expect(absoluteDifference(20, 10)).toBe(10);
    });
  });
});
